const List = () => {
  const [purchases, setPurchases] = useState([]);
  const [pageNumber, setPageNumber] = useState(0);
  const [loading, setLoading] = useState(true);
  const [refresh, setRefresh] = useState(false);
  const purchasesPerPage = 40;
